// Checkpoint lives in workflow static data, which replaces the old
// .last-checkpoint file. NOTE: static data only persists on PRODUCTION runs —
// a manual "Execute workflow" test reads it but never writes it back.
const state = $getWorkflowStaticData('global');

const now = new Date();

// A run tagged weekly (set WEEKLY_BACKLOG=true in workflow variables, or run a
// second copy of this workflow) rescans 8 days instead of trusting the
// checkpoint, to catch anything missed during a reply-volume spike.
const weekly = String($vars.WEEKLY_BACKLOG ?? 'false') === 'true';

let since;
if (weekly) {
  since = new Date(now.getTime() - 8 * 24 * 60 * 60 * 1000).toISOString();
} else if (state.lastCheckpoint) {
  since = state.lastCheckpoint;
} else {
  // First ever run: match the old script's 24-hour default.
  since = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
}

return [{ json: { since, until: now.toISOString(), weekly } }];

// Apply the scope rules from the production runbook, then emit one item per
// reply that actually needs triage.
const res = $input.first().json;
const rows = res.data ?? res.replies ?? [];
const totalCount = Number(res.total_count ?? rows.length);

// The fetch above asks for 100 in one page. If Smartlead reports more than we
// received, replies would be silently dropped — surface it loudly instead.
// (Fix when it ever fires: add offset pagination, or shorten the interval.)
if (totalCount > rows.length) {
  throw new Error(
    `Smartlead reported ${totalCount} replies in this window but only ${rows.length} were fetched. ` +
    `Replies would be dropped. Add pagination or shorten the schedule interval.`
  );
}

const out = [];
let skippedRachel = 0;
let skippedRead = 0;

for (const r of rows) {
  const campaign = String(r.email_campaign_name ?? '');

  // Rachel's campaigns have a different owner and are handled separately.
  // Never touch category, pause state, or block list for these.
  if (campaign.startsWith('Rachel -')) { skippedRachel++; continue; }

  if (r.has_new_unread_email !== true) { skippedRead++; continue; }

  // Pull the most recent inbound message out of the thread history.
  const history = r.email_history ?? [];
  const inbound = history.filter((m) => m.type === 'REPLY');
  const latest = inbound[inbound.length - 1] ?? {};
  const bodyHtml = String(latest.email_body ?? r.email_body ?? '');
  const bodyText = bodyHtml
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (!bodyText) continue;

  const email = String(r.lead_email ?? latest.from ?? '').trim().toLowerCase();
  const domain = email.split('@')[1] ?? '';

  out.push({
    json: {
      campaignId: r.email_campaign_id,
      campaignName: campaign,
      leadId: r.email_lead_id,
      leadName: r.lead_name ?? '',
      leadEmail: email,
      domain,
      company: r.lead_company_name ?? '',
      replyTime: r.last_reply_time ?? null,
      replyText: bodyText.slice(0, 6000),
      counters: { skippedRachel, skippedRead, fetched: rows.length },
    },
  });
}

return out;

