// Turn one classification into an explicit action plan. Every rule here comes
// from Sections 3 and 5 of the production workflow doc — change them there
// first, then mirror the change into this table.
const reply = $('Scope Filter').item.json;
const res = $json;

// A safety decline never matches the schema — fail loudly rather than
// mis-categorising a real lead.
if (res.stop_reason === 'refusal') {
  throw new Error(`Classifier refused on lead ${reply.leadEmail}; needs manual triage.`);
}
if (res.stop_reason === 'max_tokens') {
  throw new Error(`Classifier hit max_tokens on lead ${reply.leadEmail}; output incomplete.`);
}

const textBlock = (res.content ?? []).find((b) => b.type === 'text');
if (!textBlock) {
  throw new Error(`Classifier returned no text block for ${reply.leadEmail}.`);
}

let verdict;
try {
  verdict = JSON.parse(textBlock.text);
} catch (e) {
  throw new Error(`Classifier output was not valid JSON for ${reply.leadEmail}: ${textBlock.text.slice(0, 200)}`);
}

const category = verdict.category;
const namesAlternate = verdict.names_alternate_contact === true;

// category -> Smartlead category id. Information Request collapses into
// Follow Up (5301) to match the label used in the production doc.
const CATEGORY_ID = {
  interested: 1,
  meeting_request: 2,
  not_interested: 3,
  do_not_contact: 4,
  out_of_office: 6,
  wrong_person: 7,
  unsure: 5271,
  follow_up: 5301,
  ignore: 4497,
};

const categoryId = CATEGORY_ID[category];
if (!categoryId) {
  throw new Error(`Classifier returned an unmapped category "${category}" for ${reply.leadEmail}.`);
}

const QUALIFYING = new Set(['interested', 'meeting_request', 'follow_up']);
const syncToPipedrive = QUALIFYING.has(category);

// Blocking rules:
//  - qualifying replies get blocked so no campaign re-contacts a live deal
//  - hard rejections get blocked
//  - an OOO or wrong-person reply that names a reachable colleague must NOT be
//    blocked, or that colleague becomes uncontactable
//  - unsure is left alone entirely for a human to look at
let blockDomain;
if (category === 'unsure') {
  blockDomain = false;
} else if (category === 'out_of_office' || category === 'wrong_person') {
  blockDomain = !namesAlternate;
} else {
  blockDomain = true;
}

// pause_lead: true when the lead is disqualified or fully handled.
const pauseLead = ['not_interested', 'do_not_contact', 'ignore', 'wrong_person'].includes(category);

let action = 'none';
if (syncToPipedrive) action = 'crm';
else if (blockDomain) action = 'block';

return {
  json: {
    ...reply,
    category,
    categoryId,
    confidence: verdict.confidence,
    reasoning: verdict.reasoning,
    namesAlternate,
    syncToPipedrive,
    blockDomain,
    pauseLead,
    action,
    activityType: category === 'meeting_request' ? 'meeting' : 'task',
  },
};

const lead = $('Plan Actions').item.json;
const hit = $json?.data?.items?.[0]?.item ?? null;

return {
  json: {
    ...lead,
    personId: hit?.id ?? null,
    personFound: Boolean(hit),
    orgId: hit?.organization?.id ?? null,
  },
};

const prev = $('Resolve Person').item.json;
const hit = $json?.data?.items?.[0]?.item ?? null;

return {
  json: { ...prev, orgId: hit?.id ?? null, orgFound: Boolean(hit) },
};

// Join point for: org just created / org already existed / no company known.
const prev = $('Resolve Person').item.json;
const createdOrgId = $json?.data?.id ?? null;
const carriedOrgId = $json?.orgId ?? null;

return {
  json: { ...prev, orgId: createdOrgId ?? carriedOrgId ?? prev.orgId ?? null },
};

// Every item past this point has a real personId.
// NOTE: job_title / notes / postal_address / im / birthday are deliberately
// never sent to Pipedrive — contact sync is off on this account and those
// fields 403. The reply text goes in the Activity note instead.
const prev = $('Resolve Person').item.json;

const createdPersonId = $json?.data?.id ?? null;
const createdOrgId = $json?.data?.org_id?.value ?? $json?.orgId ?? null;

const personId = createdPersonId ?? prev.personId ?? null;
if (!personId) {
  throw new Error(`No Pipedrive person resolved or created for ${prev.leadEmail}`);
}

return {
  json: { ...prev, personId, orgId: createdOrgId ?? prev.orgId ?? null },
};

// Only block when the workflow decided to AND the domain isn't already listed.
const lead = $('Plan Actions').item.json;
const existing = $json?.data ?? $json?.domain_block_list ?? [];
const list = Array.isArray(existing) ? existing : [];

const already = list.some((e) => {
  const v = String(e?.domain ?? e?.value ?? e ?? '').toLowerCase();
  return v === lead.domain.toLowerCase();
});

return {
  json: { ...lead, alreadyBlocked: already, shouldBlock: lead.blockDomain && !already },
};

// One row per lead the workflow actually acted on. Mirrors the columns of the
// old inbox-sync-log.csv so existing reporting keeps working.
const lead = $('Plan Actions').item.json;

let pipedriveAction = 'none';
try {
  const p = $('Person Ready').item.json;
  if (p?.personId) pipedriveAction = p.personFound ? 'updated' : 'created';
} catch (e) {
  // Item never went down the CRM branch — 'none' is correct.
}

let domainBlocked = 'no';
try {
  const b = $('Block Needed?').item.json;
  if (b?.alreadyBlocked) domainBlocked = 'already';
  else if (b?.shouldBlock) domainBlocked = 'yes';
} catch (e) {}

return {
  json: {
    timestamp: new Date().toISOString(),
    campaign: lead.campaignName,
    lead_name: lead.leadName,
    lead_email: lead.leadEmail,
    category_applied: lead.category,
    confidence: lead.confidence,
    pipedrive_action: pipedriveAction,
    domain_blocked: domainBlocked,
    reply_excerpt: String(lead.replyText).replace(/\s+/g, ' ').slice(0, 200),
  },
};

// Advance the checkpoint only after everything above succeeded. If any item
// threw, the workflow stops before this node and the window is retried next
// run — at worst a reply is re-processed, never skipped.
//
// A weekly backlog run must NOT move the checkpoint backwards.
const state = $getWorkflowStaticData('global');
const window = $('Read Checkpoint').first().json;

let newest = window.until;
try {
  const times = $('Scope Filter').all()
    .map((i) => i.json.replyTime)
    .filter(Boolean)
    .sort();
  if (times.length) {
    const maxReply = times[times.length - 1];
    if (new Date(maxReply) > new Date(newest)) newest = maxReply;
  }
} catch (e) {}

const prev = state.lastCheckpoint ? new Date(state.lastCheckpoint) : null;
if (!prev || new Date(newest) > prev) {
  state.lastCheckpoint = newest;
}

const processed = $input.all().length;
return [{ json: { checkpoint: state.lastCheckpoint, processed, weekly: window.weekly } }];
